{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const databasePath = process.env.DB_PATH || path.join(root, 'workboard.sqlite');
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0,
    default_priority TEXT NOT NULL DEFAULT 'Normal',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    task_order INTEGER
  );
`);
// Upgrade databases created by earlier task checkpoints.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}
if (!projectColumns.some((column) => column.name === 'default_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'");
}
const taskColumns = database.prepare('PRAGMA table_info(tasks)').all();
if (!taskColumns.some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'");
}
if (!taskColumns.some((column) => column.name === 'due_date')) {
  database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT');
}
if (!taskColumns.some((column) => column.name === 'task_order')) {
  database.exec('ALTER TABLE tasks ADD COLUMN task_order INTEGER');
}
database.exec(`
  WITH ordered AS (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY project_id ORDER BY id) - 1 AS position
    FROM tasks WHERE task_order IS NULL
  )
  UPDATE tasks SET task_order = (SELECT position FROM ordered WHERE ordered.id = tasks.id)
  WHERE task_order IS NULL
`);

function isValidDueDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || year > 9999) return false;
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return date.getUTCFullYear() === year
    && date.getUTCMonth() === month - 1
    && date.getUTCDate() === day;
}

const json = (response, status, body) => {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
};

async function serveFile(response, filename, contentType) {
  try {
    const content = await readFile(path.join(root, filename));
    response.writeHead(200, { 'content-type': contentType });
    response.end(content);
  } catch {
    response.writeHead(500);
    response.end('Unable to load application');
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');

  if (request.method === 'GET' && url.pathname === '/health') {
    return json(response, 200, { status: 'ok' });
  }

  if (url.pathname === '/api/projects' && request.method === 'GET') {
    return json(response, 200, database.prepare(`
      SELECT p.id, p.name, p.archived,
        (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS totalCount,
        (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completedCount
      FROM projects p ORDER BY p.id
    `).all().map((project) => ({ ...project, archived: Boolean(project.archived) })));
  }

  if (url.pathname === '/api/projects' && request.method === 'POST') {
    let body = '';
    for await (const chunk of request) body += chunk;
    try {
      const input = JSON.parse(body);
      const name = typeof input.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return json(response, 201, { id: Number(result.lastInsertRowid), name });
    } catch (error) {
      if (error instanceof SyntaxError) return json(response, 400, { error: 'Invalid JSON' });
      throw error;
    }
  }

  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'PATCH' && projectMatch) {
    const projectId = Number(projectMatch[1]);
    const project = database.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(response, 404, { error: 'Project not found' });
    if (project.archived) return json(response, 409, { error: 'Archived projects cannot be changed' });

    let body = '';
    for await (const chunk of request) body += chunk;
    try {
      const input = JSON.parse(body);
      if (Object.hasOwn(input, 'defaultPriority')) {
        const priorities = ['Low', 'Normal', 'High'];
        if (!priorities.includes(input.defaultPriority)) return json(response, 400, { error: 'Invalid default task priority' });
        database.prepare('UPDATE projects SET default_priority = ? WHERE id = ?').run(input.defaultPriority, projectId);
        return json(response, 200, { id: projectId, defaultPriority: input.defaultPriority });
      }
      const name = typeof input.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, projectId);
      return json(response, 200, { id: projectId, name });
    } catch (error) {
      if (error instanceof SyntaxError) return json(response, 400, { error: 'Invalid JSON' });
      throw error;
    }
  }

  if (request.method === 'GET' && projectMatch) {
    const project = database.prepare('SELECT id, name, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    if (project) project.archived = Boolean(project.archived);
    return project ? json(response, 200, project) : json(response, 404, { error: 'Project not found' });
  }

  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (archiveMatch && request.method === 'POST') {
    const archived = archiveMatch[2] === 'archive';
    const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?')
      .run(archived ? 1 : 0, Number(archiveMatch[1]));
    if (!result.changes) return json(response, 404, { error: 'Project not found' });
    return json(response, 200, { id: Number(archiveMatch[1]), archived });
  }

  const projectTasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (projectTasksMatch && request.method === 'GET') {
    const projectId = Number(projectTasksMatch[1]);
    const project = database.prepare('SELECT id, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(response, 404, { error: 'Project not found' });
    return json(response, 200, database.prepare(
      'SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY task_order, id'
    ).all(projectId).map((task) => ({ ...task, completed: Boolean(task.completed) })));
  }

  if (projectTasksMatch && request.method === 'POST') {
    const projectId = Number(projectTasksMatch[1]);
    const project = database.prepare('SELECT id, archived, default_priority AS defaultPriority FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(response, 404, { error: 'Project not found' });
    if (project.archived) return json(response, 409, { error: 'Archived projects cannot have new tasks' });
    let body = '';
    for await (const chunk of request) body += chunk;
    try {
      const input = JSON.parse(body);
      const title = typeof input.title === 'string' ? input.title.trim() : '';
      if (!title) return json(response, 400, { error: 'Task title is required' });
      const position = database.prepare('SELECT COALESCE(MAX(task_order), -1) + 1 AS next FROM tasks WHERE project_id = ?').get(projectId).next;
      const result = database.prepare('INSERT INTO tasks (project_id, title, priority, task_order) VALUES (?, ?, ?, ?)')
        .run(projectId, title, project.defaultPriority, position);
      return json(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false, priority: project.defaultPriority });
    } catch (error) {
      if (error instanceof SyntaxError) return json(response, 400, { error: 'Invalid JSON' });
      throw error;
    }
  }

  const moveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
  if (moveMatch && request.method === 'POST') {
    const sourceId = Number(moveMatch[1]);
    const taskId = Number(moveMatch[2]);
    const source = database.prepare('SELECT archived FROM projects WHERE id = ?').get(sourceId);
    if (!source) return json(response, 404, { error: 'Project not found' });
    if (source.archived) return json(response, 409, { error: 'Archived projects cannot move tasks' });
    let body = '';
    for await (const chunk of request) body += chunk;
    try {
      const input = JSON.parse(body);
      const destinationId = Number(input.destinationProjectId);
      const destination = database.prepare('SELECT id, archived FROM projects WHERE id = ?').get(destinationId);
      if (!destination || destination.archived || destinationId === sourceId) {
        return json(response, 400, { error: 'Invalid destination project' });
      }
      const task = database.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?').get(taskId, sourceId);
      if (!task) return json(response, 404, { error: 'Task not found' });
      const position = database.prepare('SELECT COALESCE(MAX(task_order), -1) + 1 AS next FROM tasks WHERE project_id = ?').get(destinationId).next;
      database.prepare('UPDATE tasks SET project_id = ?, task_order = ? WHERE id = ?').run(destinationId, position, taskId);
      return json(response, 200, { id: taskId, projectId: destinationId });
    } catch (error) {
      if (error instanceof SyntaxError) return json(response, 400, { error: 'Invalid JSON' });
      throw error;
    }
  }

  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(response, 404, { error: 'Project not found' });
    if (project?.archived) return json(response, 409, { error: 'Archived project tasks cannot be changed' });
    let body = '';
    for await (const chunk of request) body += chunk;
    try {
      const input = JSON.parse(body);
      if (!input || typeof input !== 'object' || Array.isArray(input)) {
        return json(response, 400, { error: 'Invalid request body' });
      }
      const task = database.prepare('SELECT id, title, completed FROM tasks WHERE id = ? AND project_id = ?')
        .get(taskId, projectId);
      if (!task) return json(response, 404, { error: 'Task not found' });

      if (Object.hasOwn(input, 'title')) {
        const title = typeof input.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?').run(title, taskId, projectId);
        return json(response, 200, { id: taskId, projectId, title, completed: Boolean(task.completed) });
      }
      if (Object.hasOwn(input, 'priority')) {
        const priorities = ['Low', 'Normal', 'High'];
        if (!priorities.includes(input.priority)) return json(response, 400, { error: 'Invalid task priority' });
        database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?')
          .run(input.priority, taskId, projectId);
        return json(response, 200, { id: taskId, projectId, priority: input.priority });
      }
      if (Object.hasOwn(input, 'dueDate')) {
        const dueDate = typeof input.dueDate === 'string' ? input.dueDate.trim() : '';
        if (dueDate && !isValidDueDate(dueDate)) {
          return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
        }
        const canonicalDate = dueDate || null;
        database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?')
          .run(canonicalDate, taskId, projectId);
        return json(response, 200, { id: taskId, projectId, dueDate: canonicalDate });
      }
      if (typeof input.completed !== 'boolean') return json(response, 400, { error: 'Completion state is required' });
      database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?')
        .run(input.completed ? 1 : 0, taskId, projectId);
      return json(response, 200, { id: taskId, projectId, completed: input.completed });
    } catch (error) {
      if (error instanceof SyntaxError) return json(response, 400, { error: 'Invalid JSON' });
      throw error;
    }
  }

  if (request.method === 'GET' && url.pathname === '/') {
    return serveFile(response, 'index.html', 'text/html; charset=utf-8');
  }
  if (request.method === 'GET' && url.pathname === '/app.js') {
    return serveFile(response, 'app.js', 'text/javascript; charset=utf-8');
  }
  if (request.method === 'GET' && url.pathname === '/styles.css') {
    return serveFile(response, 'styles.css', 'text/css; charset=utf-8');
  }
  if (request.method === 'GET' && /^\/projects\/\d+$/.test(url.pathname)) {
    return serveFile(response, 'index.html', 'text/html; charset=utf-8');
  }

  response.writeHead(404);
  response.end('Not found');
});

const port = Number.parseInt(process.env.PORT || '8080', 10);
const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projectList = document.querySelector('#projects');
const form = document.querySelector('#create-project-form');
const nameInput = document.querySelector('#project-name');
const alert = document.querySelector('#form-alert');
const taskForm = document.querySelector('#create-task-form');
const taskInput = document.querySelector('#task-title');
const taskAlert = document.querySelector('#task-alert');
const taskList = document.querySelector('#tasks');
const taskFilter = document.querySelector('#task-filter');
const defaultTaskPriority = document.querySelector('#default-task-priority');
const priorityFilter = document.querySelector('#priority-filter');
const taskRenameAlert = document.querySelector('#task-rename-alert');
const taskDateAlert = document.querySelector('#task-date-alert');
const dueFromInput = document.querySelector('#due-from');
const dueThroughInput = document.querySelector('#due-through');
const dueRangeAlert = document.querySelector('#due-range-alert');
let appliedDueRange = { from: '', through: '' };
const projectFilter = document.querySelector('#project-filter');
const archivedNotice = document.querySelector('#archived-notice');
const renameForm = document.querySelector('#rename-project-form');
const renameInput = document.querySelector('#new-project-name');
const renameAlert = document.querySelector('#rename-alert');
let activeProjectId = null;
let activeProjectArchived = false;
let activeProjectDefaultPriority = 'Normal';

async function fetchProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

function renderProjects(projects) {
  projectList.replaceChildren();
  const archived = projectFilter.value === 'Archived';
  for (const project of projects.filter((item) => item.archived === archived)) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => navigate(`/projects/${project.id}`));
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const archive = document.createElement('button');
    archive.type = 'button';
    archive.textContent = archived ? 'Restore project' : 'Archive project';
    archive.addEventListener('click', async () => {
      const action = archived ? 'restore' : 'archive';
      const response = await fetch(`/api/projects/${project.id}/${action}`, { method: 'POST' });
      if (response.ok) renderProjects(await fetchProjects());
    });
    row.append(name, summary, open, archive);
    projectList.append(row);
  }
}

async function showList() {
  listView.hidden = false;
  detailView.hidden = true;
  renderProjects(await fetchProjects());
}

async function showProject(id) {
  const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
  if (!response.ok) {
    navigate('/');
    return;
  }
  const project = await response.json();
  taskFilter.value = 'All';
  priorityFilter.value = 'All';
  dueFromInput.value = '';
  dueThroughInput.value = '';
  appliedDueRange = { from: '', through: '' };
  dueRangeAlert.hidden = true;
  document.querySelector('#detail-heading').textContent = project.name;
  activeProjectId = id;
  activeProjectArchived = project.archived;
  activeProjectDefaultPriority = project.defaultPriority;
  defaultTaskPriority.value = project.defaultPriority;
  defaultTaskPriority.disabled = activeProjectArchived;
  archivedNotice.hidden = !activeProjectArchived;
  renameInput.disabled = activeProjectArchived;
  renameForm.querySelector('button').disabled = activeProjectArchived;
  taskForm.querySelectorAll('input, button').forEach((control) => { control.disabled = activeProjectArchived; });
  listView.hidden = true;
  detailView.hidden = false;
  taskAlert.hidden = true;
  await refreshTasks();
}

async function refreshTasks() {
  if (!activeProjectId) return;
  const response = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks`);
  if (!response.ok) throw new Error('Could not load tasks');
  const tasks = await response.json();
  const destinations = (await fetchProjects()).filter((project) => !project.archived && String(project.id) !== String(activeProjectId));
  const filter = taskFilter.value;
  const selectedPriority = priorityFilter.value;
  taskList.replaceChildren();
  for (const task of tasks) {
    if (filter === 'Open' && task.completed || filter === 'Completed' && !task.completed) continue;
    if (selectedPriority !== 'All' && task.priority !== selectedPriority) continue;
    if ((appliedDueRange.from || appliedDueRange.through) && !task.dueDate) continue;
    if (appliedDueRange.from && task.dueDate < appliedDueRange.from) continue;
    if (appliedDueRange.through && task.dueDate > appliedDueRange.through) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = activeProjectArchived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      const update = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ completed: checkbox.checked }),
      });
      if (!update.ok) {
        checkbox.checked = task.completed;
        taskAlert.textContent = 'Unable to update task';
        taskAlert.hidden = false;
        return;
      }
      await refreshTasks();
    });

    const renameForm = document.createElement('form');
    renameForm.className = 'task-rename-form';
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.setAttribute('aria-label', 'New task title');
    renameInput.value = task.title;
    renameInput.disabled = activeProjectArchived;
    const renameButton = document.createElement('button');
    renameButton.type = 'submit';
    renameButton.textContent = 'Rename task';
    renameButton.disabled = activeProjectArchived;
    renameForm.append(renameInput, renameButton);
    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      const newTitle = renameInput.value.trim();
      if (!newTitle) {
        taskRenameAlert.textContent = 'Task title is required';
        taskRenameAlert.hidden = false;
        return;
      }
      taskRenameAlert.hidden = true;
      const update = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ title: newTitle }),
      });
      if (!update.ok) {
        taskRenameAlert.textContent = 'Unable to rename task';
        taskRenameAlert.hidden = false;
        return;
      }
      await refreshTasks();
    });

    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority;
    priority.disabled = activeProjectArchived;
    priority.addEventListener('change', async () => {
      const update = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ priority: priority.value }),
      });
      if (!update.ok) {
        priority.value = task.priority;
        taskAlert.textContent = 'Unable to update task priority';
        taskAlert.hidden = false;
        return;
      }
      await refreshTasks();
    });

    const dueDateForm = document.createElement('form');
    dueDateForm.className = 'task-due-date-form';
    const dueDateInput = document.createElement('input');
    dueDateInput.type = 'text';
    dueDateInput.setAttribute('aria-label', 'Task due date');
    dueDateInput.placeholder = 'YYYY-MM-DD';
    dueDateInput.value = task.dueDate || '';
    dueDateInput.disabled = activeProjectArchived;
    const saveDueDate = document.createElement('button');
    saveDueDate.type = 'submit';
    saveDueDate.textContent = 'Save due date';
    saveDueDate.disabled = activeProjectArchived;
    dueDateForm.append(dueDateInput, saveDueDate);
    dueDateForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      const response = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${task.id}`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ dueDate: dueDateInput.value }),
      });
      if (!response.ok) {
        taskDateAlert.textContent = 'Due date must be a valid YYYY-MM-DD date';
        taskDateAlert.hidden = false;
        return;
      }
      taskDateAlert.hidden = true;
      await refreshTasks();
    });

    const moveForm = document.createElement('form');
    moveForm.className = 'task-move-form';
    const destination = document.createElement('select');
    destination.setAttribute('aria-label', 'Destination project');
    for (const project of destinations) {
      const option = document.createElement('option');
      option.value = project.id;
      option.textContent = project.name;
      destination.append(option);
    }
    destination.disabled = activeProjectArchived || destinations.length === 0;
    const moveButton = document.createElement('button');
    moveButton.type = 'submit';
    moveButton.textContent = 'Move task';
    moveButton.disabled = destination.disabled;
    moveForm.append(destination, moveButton);
    moveForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      const moved = await fetch(`/api/projects/${encodeURIComponent(activeProjectId)}/tasks/${task.id}/move`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ destinationProjectId: Number(destination.value) }),
      });
      if (!moved.ok) {
        taskAlert.textContent = 'Unable to move task';
        taskAlert.hidden = false;
        return;
      }
      await refreshTasks();
    });

    row.append(title, renameForm, priority, dueDateForm, moveForm, checkbox);
    taskList.append(row);
  }
}

function navigate(path) {
  history.pushState({}, '', path);
  renderRoute();
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  try {
    if (match) await showProject(match[1]);
    else await showList();
  } catch {
    listView.hidden = false;
    detailView.hidden = true;
    alert.textContent = 'Unable to load projects';
    alert.hidden = false;
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const name = nameInput.value.trim();
  if (!name) {
    alert.textContent = 'Project name is required';
    alert.hidden = false;
    return;
  }
  alert.hidden = true;
  const response = await fetch('/api/projects', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name }),
  });
  if (!response.ok) {
    alert.textContent = 'Unable to create project';
    alert.hidden = false;
    return;
  }
  nameInput.value = '';
  renderProjects(await fetchProjects());
});

document.querySelector('#back-to-projects').addEventListener('click', () => navigate('/'));
renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  const name = renameInput.value.trim();
  if (!name) {
    renameAlert.textContent = 'Project name is required';
    renameAlert.hidden = false;
